use crate::{ParseError, span};
use alloc::string::{String, ToString};
use alloc::vec::Vec;
use core::fmt;
use core::range::Range;
use proc_macro2::{
    Delimiter, Group, Ident, LineColumn, Literal, Punct, Spacing, Span as TokenSpan, TokenStream,
    TokenTree,
};

/// The text of a token stream, rebuilt from the positions of its tokens, together with a map
/// from byte offsets of the text back to the tokens.
///
/// This lets a parser generated by prpr parse the input of a proc-macro as text and report
/// errors at the right tokens:
///
/// ```ignore
/// #[proc_macro]
/// pub fn my_dsl(input: proc_macro::TokenStream) -> proc_macro::TokenStream {
///     let src = prpr_runtime::SourceText::new(input.into());
///     match my_grammar::program(src.text()) {
///         Ok(ast) => expand(ast).into(),
///         Err(e) => src.parse_error(&e).into(),
///     }
/// }
/// ```
///
/// The layout of the original source is reproduced from `Span::start` and `Span::end`, except
/// that comments become spaces. Where token positions are unavailable or inconsistent (e.g. for
/// tokens produced by `macro_rules!`), tokens are separated by single spaces, and joint
/// punctuation is kept together.
pub struct SourceText {
    text: String,
    nodes: Vec<Node>,
    // Every token and delimiter in text order.
    marks: Vec<(Range<usize>, TokenSpan)>,
}

enum Node {
    Leaf(TokenTree, Range<usize>),
    Group {
        group: Group,
        open: Range<usize>,
        close: Range<usize>,
        children: Vec<Node>,
    },
}

impl SourceText {
    /// Rebuilds the text of `tokens`, e.g. the input of a proc-macro.
    pub fn new(tokens: TokenStream) -> Self {
        let mut builder = Builder {
            text: String::new(),
            last: None,
            joint: false,
            marks: Vec::new(),
        };
        let nodes = builder.stream(tokens);
        SourceText {
            text: builder.text,
            nodes,
            marks: builder.marks,
        }
    }

    /// The text, to be parsed.
    pub fn text(&self) -> &str {
        &self.text
    }

    /// The original tokens that lie within `range` of the text.
    pub fn tokens(&self, range: Range<usize>) -> TokenStream {
        let mut out = TokenStream::new();
        collect(&self.nodes, range, &mut out);
        out
    }

    /// The span of the token at `offset` of the text, or of the next token if `offset` is
    /// between tokens.
    pub fn span(&self, offset: usize) -> TokenSpan {
        let i = self.marks.partition_point(|(r, _)| r.end <= offset);
        match self.marks.get(i).or(self.marks.last()) {
            Some((_, span)) => *span,
            None => TokenSpan::call_site(),
        }
    }

    /// The spans of the first and the last token of `range` of the text.
    pub fn span_range(&self, range: Range<usize>) -> (TokenSpan, TokenSpan) {
        let last = range.end.saturating_sub(1).max(range.start);
        (self.span(range.start), self.span(last))
    }

    /// A `compile_error!` invocation that reports `message` at `range` of the text.
    pub fn compile_error(&self, range: Range<usize>, message: &str) -> TokenStream {
        let (start, end) = self.span_range(range);
        compile_error(start, end, message)
    }

    /// A `compile_error!` invocation that reports a parse error of the text.
    pub fn parse_error(&self, error: &ParseError) -> TokenStream {
        self.compile_error(error.span(), &error.to_string())
    }

    /// Runs `f` on the text of `tokens`, e.g. the input of a proc-macro, and returns the tokens
    /// that `f` returns, or a `compile_error!` invocation that reports its error.
    ///
    /// ```ignore
    /// #[proc_macro]
    /// pub fn my_dsl(input: proc_macro::TokenStream) -> proc_macro::TokenStream {
    ///     SourceText::with(input.into(), |src| {
    ///         let ast = my_grammar::program(src.text())?;
    ///         expand(src, ast)
    ///     })
    ///     .into()
    /// }
    /// ```
    pub fn with(
        tokens: TokenStream,
        f: impl FnOnce(&SourceText) -> Result<TokenStream, MacroError>,
    ) -> TokenStream {
        let src = SourceText::new(tokens);
        f(&src).unwrap_or_else(|e| src.compile_error(e.span, &e.message))
    }
}

/// An error to report at a range of the text of a [`SourceText`], e.g. a parse error or a
/// mistake found in the parsed input of a proc-macro.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MacroError {
    /// The byte range of the text that the error is about.
    pub span: Range<usize>,
    /// What is wrong.
    pub message: String,
}

impl MacroError {
    /// An error at `span` of the text.
    pub fn new(span: Range<usize>, message: impl Into<String>) -> Self {
        MacroError {
            span,
            message: message.into(),
        }
    }
}

impl From<ParseError> for MacroError {
    fn from(error: ParseError) -> Self {
        MacroError::new(error.span(), error.to_string())
    }
}

impl fmt::Display for MacroError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.message)
    }
}

impl core::error::Error for MacroError {}

// Whether `inner` lies within `outer`.
fn covers(outer: Range<usize>, inner: Range<usize>) -> bool {
    outer.start <= inner.start && inner.end <= outer.end
}

fn collect(nodes: &[Node], range: Range<usize>, out: &mut TokenStream) {
    for node in nodes {
        match node {
            Node::Leaf(tt, r) => {
                if covers(range, *r) {
                    out.extend([tt.clone()]);
                }
            }
            Node::Group {
                group,
                open,
                close,
                children,
            } => {
                let full = span(open.start, close.end);
                if covers(range, full) {
                    out.extend([TokenTree::Group(group.clone())]);
                } else if full.start < range.end && range.start < full.end {
                    collect(children, range, out);
                }
            }
        }
    }
}

// Spans the leading tokens at `start` and the trailing group at `end`, so that the compiler
// reports the range from `start` to `end` (the technique of `syn::Error`).
fn compile_error(start: TokenSpan, end: TokenSpan, message: &str) -> TokenStream {
    let punct = |c, spacing| {
        let mut p = Punct::new(c, spacing);
        p.set_span(start);
        TokenTree::Punct(p)
    };
    let mut lit = Literal::string(message);
    lit.set_span(end);
    let mut group = Group::new(Delimiter::Brace, TokenTree::Literal(lit).into());
    group.set_span(end);
    [
        punct(':', Spacing::Joint),
        punct(':', Spacing::Alone),
        TokenTree::Ident(Ident::new("core", start)),
        punct(':', Spacing::Joint),
        punct(':', Spacing::Alone),
        TokenTree::Ident(Ident::new("compile_error", start)),
        punct('!', Spacing::Alone),
        TokenTree::Group(group),
    ]
    .into_iter()
    .collect()
}

struct Builder {
    text: String,
    // The end of the last token with a usable position.
    last: Option<LineColumn>,
    // Whether the last token was a punctuation joined to the next one.
    joint: bool,
    marks: Vec<(Range<usize>, TokenSpan)>,
}

impl Builder {
    fn stream(&mut self, tokens: TokenStream) -> Vec<Node> {
        tokens.into_iter().map(|tt| self.tree(tt)).collect()
    }

    fn tree(&mut self, tt: TokenTree) -> Node {
        match tt {
            TokenTree::Group(group) => {
                let (open, close) = match group.delimiter() {
                    Delimiter::Parenthesis => ("(", ")"),
                    Delimiter::Brace => ("{", "}"),
                    Delimiter::Bracket => ("[", "]"),
                    Delimiter::None => ("", ""),
                };
                let open = self.emit(group.span_open(), open, false);
                let children = self.stream(group.stream());
                let close = self.emit(group.span_close(), close, false);
                Node::Group {
                    group,
                    open,
                    close,
                    children,
                }
            }
            TokenTree::Punct(p) => {
                let joint = p.spacing() == Spacing::Joint;
                let span = self.emit(p.span(), p.as_char().encode_utf8(&mut [0; 4]), joint);
                Node::Leaf(TokenTree::Punct(p), span)
            }
            TokenTree::Ident(i) => {
                let span = self.emit(i.span(), &i.to_string(), false);
                Node::Leaf(TokenTree::Ident(i), span)
            }
            TokenTree::Literal(l) => {
                let span = self.emit(l.span(), &l.to_string(), false);
                Node::Leaf(TokenTree::Literal(l), span)
            }
        }
    }

    fn emit(&mut self, token: TokenSpan, s: &str, joint: bool) -> Range<usize> {
        if s.is_empty() {
            let at = self.text.len();
            return span(at, at);
        }
        let (start, end) = (token.start(), token.end());
        // A token without extent has no usable position.
        let located = pos(end) > pos(start);
        if !self.text.is_empty() {
            match self.last {
                Some(last) if located && pos(start) >= pos(last) => {
                    if start.line > last.line {
                        self.pad('\n', start.line - last.line);
                        self.pad(' ', start.column);
                    } else {
                        self.pad(' ', start.column - last.column);
                    }
                }
                _ if self.joint => {}
                _ => self.text.push(' '),
            }
        }
        let begin = self.text.len();
        self.text.push_str(s);
        if located {
            self.last = Some(match self.last {
                Some(last) if pos(last) > pos(end) => last,
                _ => end,
            });
        }
        self.joint = joint;
        let range = span(begin, self.text.len());
        self.marks.push((range, token));
        range
    }

    fn pad(&mut self, c: char, n: usize) {
        self.text.extend(core::iter::repeat_n(c, n));
    }
}

fn pos(lc: LineColumn) -> (usize, usize) {
    (lc.line, lc.column)
}
